fn main() {
    let b = Box::new(5);
    println!("b = {b}");
    let sum = *b + 1;  // * follows the pointer
    println!("sum = {sum}");

    let big = Box::new([0u8; 1_000_000]); // a megabyte on the heap
    let moved = big;                      // moves 8 bytes, not a megabyte
    println!("{} bytes, box is {} bytes", moved.len(), std::mem::size_of_val(&moved));
}

